local LUA_PATH_COMMON_EMOJI = "Game.UI.UIBattling.BattlePVP.CommonEmojiNode"
------------ import ------------

------------ define ------------
------------ define ------------

---@class UIBattlingPVPMsgCell
local UIBattlingPVPMsgCell = Class('UIBattlingPVPMsgCell')

------------ lifeCycle ------------
function UIBattlingPVPMsgCell:__init()
    self.listEmojiNode = {}
end

function UIBattlingPVPMsgCell:__delete()
    self.listEmojiNode = nil
end

function UIBattlingPVPMsgCell:Awake()
    self:InitEmojiNode()
end

function UIBattlingPVPMsgCell:Start()
end

function UIBattlingPVPMsgCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------

------------ init ------------
function UIBattlingPVPMsgCell:InitEmojiNode()
    for i = 1, 8 do
        local itemName = string.format("Item%d", i)
        local transEmojiNode = self.controller.transform:Find(itemName)
        if not IsNull(transEmojiNode) then
            local lb_EmojiNode = GetLuaBehaviour(transEmojiNode.gameObject, LUA_PATH_COMMON_EMOJI)
            if not IsNull(lb_EmojiNode) then
                lb_EmojiNode:Init()
                local lt_EmojiNode = lb_EmojiNode.Env
                table.insert(self.listEmojiNode, lt_EmojiNode)
            end
        end
    end
end
------------ init ------------

function UIBattlingPVPMsgCell:SetCellEmoji(emojiDataList)
    for i = 1, #self.listEmojiNode do
        self.listEmojiNode[i]:SetNodeActive(not isNull(emojiDataList[i]))
        if emojiDataList[i] then
            self.listEmojiNode[i]:SetEmojiListItem(emojiDataList[i])
        end
    end
end

return UIBattlingPVPMsgCell